from datetime import date
from typing import List, Dict, Optional

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = holidays or []
        # Track used leave days per employee per year: {employee: {year: days_used}}
        self.used_days: Dict[str, Dict[int, int]] = {}

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        # Check if end date is before start date
        if end < start:
            raise ValueError("End date cannot be before start date")

        # Check if request is made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Request must be made at least 3 days before start date")

        # Calculate the number of calendar days in the range (inclusive)
        delta = end - start
        total_days = delta.days + 1

        # Count weekends and holidays to exclude from leave days
        leave_days = 0
        current_date = start
        while current_date <= end:
            # Skip weekends (Saturday=5, Sunday=6)
            if current_date.weekday() < 5:
                # Skip holidays
                if current_date not in self.holidays:
                    leave_days += 1
            current_date += date.resolution

        # Get the year for this request
        year = start.year

        # Get remaining days for this employee and year
        remaining_days = self.remaining(employee, year)

        # Check if there are enough remaining days
        if leave_days > remaining_days:
            raise ValueError("Not enough remaining leave days")

        # Record the used days
        if employee not in self.used_days:
            self.used_days[employee] = {}
        if year not in self.used_days[employee]:
            self.used_days[employee][year] = 0
        self.used_days[employee][year] += leave_days

        return leave_days

    def remaining(self, employee: str, year: int) -> int:
        # Get used days for this employee and year, default to 0 if not found
        used = self.used_days.get(employee, {}).get(year, 0)
        return self.days_per_year - used
